def validate_seeded_answers_simple(answers, options, algo):
    """
    This validator checks if the answers includes all possible options

    Args:
        answers (str): the answers to be checked
        options (dict): all options that should exist in the answers
        algo (str): selection algorithm

    Returns:
        None if everything is good. Otherwise, the missing option error message.
    """
    seen_options = {}
    for answer in answers:
        if answer:
            key = options[answer['answer']].get('text')
            if options[answer['answer']].get('image_url'):
                key += options[answer['answer']].get('image_url')
            seen_options.setdefault(key, 0)
            seen_options[key] += 1

    missing_options = []
    index = 1
    for option in options:
        key = option.get('text') + option.get('image_url') if option.get('image_url') else option.get('text')
        if option.get('text') != 'n/a':
            if seen_options.get(key, 0) == 0:
                missing_options.append(_('Option ') + str(index))
            index += 1

    if missing_options:
        return {'seed_error': _('Missing option seed(s): ') + ', '.join(missing_options)}

    return None

def ensure_ajax(valid_request_methods, error_response_context=None):
    """
    Intends to ensure the received the request is ajax request and it is
    included in the valid request methods

    :param valid_request_methods: list: list of valid request methods, such as
      'GET', 'POST'
    :param error_response_context: None/dict: context dictionary to render, if
      error occurs
    :return: function
    """
    def real_decorator(view_func):
        def wrap_func(request, *args, **kwargs):
            if not isinstance(request, HttpRequest):
                # make sure the request is a django httprequest
                return generate_error_json_response("Invalid request!",
                                                    error_response_context)
            elif not request.is_ajax():
                # ensure the request is an ajax request
                return generate_error_json_response("Invalid request type!",
                                                    error_response_context)
            elif request.method not in valid_request_methods:
                # check if the request method is in allowed request methods
                return generate_error_json_response("Invalid request method!",
                                                    error_response_context)
            else:
                return view_func(request, *args, **kwargs)
        wrap_func.__doc__ = view_func.__doc__
        wrap_func.__name__ = view_func.__name__
        return wrap_func
    return real_decorator

