def badge_color(self):
        """Find the badge color based on the thresholds."""
        # If no thresholds were passed then return the default color
        if not self.thresholds:
            return self.default_color

        if self.value_type == str:
            if self.value in self.thresholds:
                return self.thresholds[self.value]
            else:
                return self.default_color

        # Convert the threshold dictionary into a sorted list of lists
        threshold_list = [[self.value_type(i[0]), i[1]] for i in self.thresholds.items()]
        threshold_list.sort(key=lambda x: x[0])

        color = None

        for threshold, color in threshold_list:
            if float(self.value) < float(threshold):
                return color

        # If we drop out the top of the range then return the last max color
        if color and self.use_max_when_value_exceeds:
            return color
        else:
            return self.default_color

def get_max_id(self, object_type, role):
        """Get the highest used ID."""
        if object_type == 'user':
            objectclass = 'posixAccount'
            ldap_attr = 'uidNumber'
        elif object_type == 'group':  # pragma: no cover
            objectclass = 'posixGroup'
            ldap_attr = 'gidNumber'
        else:
            raise ldap_tools.exceptions.InvalidResult('Unknown object type')

        minID, maxID = Client.__set_id_boundary(role)

        filter = [
            "(objectclass={})".format(objectclass), "({}>={})".format(ldap_attr, minID)
        ]

        if maxID is not None:
            filter.append("({}<={})".format(ldap_attr, maxID))

        id_list = self.search(filter, [ldap_attr])

        if id_list == []:
            id = minID
        else:
            if object_type == 'user':
                id = max([i.uidNumber.value for i in id_list]) + 1
            elif object_type == 'group':
                id = max([i.gidNumber.value for i in id_list]) + 1
            else:
                raise ldap_tools.exceptions.InvalidResult('Unknown object')

        return id

