def _prepare_uri(self, service_name, **parameters):
        """Prepare the URI for a request

        :param service_name: The target service
        :type service_name: str
        :param kwargs: query parameters
        :return: The uri of the request
        """
        query_parameters = []
        for key, value in parameters.items():
            if isinstance(value, (list, tuple)):
                value = ",".join([str(member) for member in value])
            if isinstance(value, bool):
                value = "true" if value else "false"
            query_parameters.append("{}={}".format(key, value))

        if query_parameters:
            uri = "{}{}?{}".format(self.base_url, service_name,
                                   "&".join(query_parameters))
        else:
            uri = "{}{}".format(self.base_url, service_name)
        return uri

def _remote(self, name):
        """Return a remote for which 'name' matches the short_name or url """
        from ambry.orm import Remote
        from sqlalchemy import or_
        from ambry.orm.exc import NotFoundError
        from sqlalchemy.orm.exc import NoResultFound, MultipleResultsFound

        if not name.strip():
            raise NotFoundError("Empty remote name")

        try:
            try:
                r = self.database.session.query(Remote).filter(Remote.short_name == name).one()
            except NoResultFound as e:
                r = None

            if not r:
                r = self.database.session.query(Remote).filter(Remote.url == name).one()

        except NoResultFound as e:
            raise NotFoundError(str(e)+'; '+name)
        except MultipleResultsFound as e:
            self.logger.error("Got multiple results for search for remote '{}': {}".format(name, e))
            return None

        return r

def convertBits(self, sigOrVal, toType):
    """
    Cast signed-unsigned, to int or bool
    """
    if isinstance(sigOrVal, Value):
        return convertBits__val(self, sigOrVal, toType)
    elif isinstance(toType, HBool):
        if self.bit_length() == 1:
            v = 0 if sigOrVal._dtype.negated else 1
            return sigOrVal._eq(self.getValueCls().fromPy(v, self))
    elif isinstance(toType, Bits):
        if self.bit_length() == toType.bit_length():
            return sigOrVal._convSign(toType.signed)
    elif toType == INT:
        return Operator.withRes(AllOps.BitsToInt, [sigOrVal], toType)

    return default_auto_cast_fn(self, sigOrVal, toType)

def mapBucketIndexToNonZeroBits(self, index):
    """
    Given a bucket index, return the list of non-zero bits. If the bucket
    index does not exist, it is created. If the index falls outside our range
    we clip it.

    :param index The bucket index to get non-zero bits for.
    @returns numpy array of indices of non-zero bits for specified index.
    """
    if index < 0:
      index = 0

    if index >= self._maxBuckets:
      index = self._maxBuckets-1

    if not self.bucketMap.has_key(index):
      if self.verbosity >= 2:
        print "Adding additional buckets to handle index=", index
      self._createBucket(index)
    return self.bucketMap[index]

