def get_ssh_agent_keys(logger):
    """
    Ask the SSH agent for a list of keys, and return it.

    :return: A reference to the SSH agent and a list of keys.
    """
    agent, agent_keys = None, None

    try:
        agent = paramiko.agent.Agent()
        _agent_keys = agent.get_keys()

        if not _agent_keys:
            agent.close()
            logger.error(
                "SSH agent didn't provide any valid key. Trying to continue..."
            )
        else:
            agent_keys = tuple(k for k in _agent_keys)
    except paramiko.SSHException:
        if agent:
            agent.close()
            agent = None
        logger.error("SSH agent speaks a non-compatible protocol. Ignoring it.")
    finally:
        return agent, agent_keys

def send_jsonified(self, msg, stats=True):
        """Send JSON-encoded message

        `msg`
            JSON encoded string to send
        `stats`
            If set to True, will update statistics after operation completes
        """
        msg = bytes_to_str(msg)

        if self._immediate_flush:
            if self.handler and self.handler.active and not self.send_queue:
                # Send message right away
                self.handler.send_pack('a[%s]' % msg)
            else:
                if self.send_queue:
                    self.send_queue += ','
                self.send_queue += msg

                self.flush()
        else:
            if self.send_queue:
                self.send_queue += ','
            self.send_queue += msg

            if not self._pending_flush:
                self.server.io_loop.add_callback(self.flush)
                self._pending_flush = True

        if stats:
            self.stats.on_pack_sent(1)

def _sig(self, name, dtype=BIT, defVal=None):
        """
        Create signal in this unit
        """
        if isinstance(dtype, HStruct):
            if defVal is not None:
                raise NotImplementedError()
            container = dtype.fromPy(None)
            for f in dtype.fields:
                if f.name is not None:
                    r = self._sig("%s_%s" % (name, f.name), f.dtype)
                    setattr(container, f.name, r)

            return container

        return self._ctx.sig(name, dtype=dtype, defVal=defVal)

