    """Try various RFC conversions to ``datetime`` or return ``None``.

    :param date_str: Date string.
    :type  date_str: ``string``
    :return: Date time.
    :rtype:  :class:`datetime.datetime` or ``None``
    """
    convert_fns = (
        dt_from_rfc8601,
