def walk(self, leavesonly=True, maxdepth=None, _depth = 0):
        """Depth-first search, walking through trie, returning all encounterd nodes (by default only leaves)"""
        if self.children:
            if not maxdepth or (maxdepth and _depth < maxdepth):
                for key, child in self.children.items():
                    if child.leaf():
                        yield child
                    else:
                        for results in child.walk(leavesonly, maxdepth, _depth + 1):
                            yield results

def getFirstElementCustomFilter(self, filterFunc, root='root'):
        '''
            getFirstElementCustomFilter - Scan elements using a provided function, stop and return the first match.

                @see getElementsCustomFilter to match multiple elements

            @param filterFunc <function>(node) - A function that takes an AdvancedTag as an argument, and returns True if some arbitrary criteria is met

            @return - An AdvancedTag of the node that matched, or None if no match.
        '''
        (root, isFromRoot) = self._handleRootArg(root)

        elements = []

        if isFromRoot is True and filterFunc(root) is True:
            return root

        getFirstElementCustomFilter = self.getFirstElementCustomFilter

        for child in root.children:

            if filterFunc(child) is True:
                return child

            subRet = getFirstElementCustomFilter(filterFunc, child)

            if subRet:
                return subRet

        return None

def get_full_dependents(self, term_id, relations, counter = 0):
        """
        Returns the complete list of dependents and embedded dependents of a certain term.
        """
        counter += 1
        deps = self.relations_for_term
        if term_id in deps and len(deps.get(term_id)) > 0:
            for dep in deps.get(term_id):
                if not dep[1] in relations:
                    relations.append(dep[1])
                    if dep[1] in deps:
                        deprelations = self.get_full_dependents(dep[1], relations, counter)
                        for deprel in deprelations:
                            if not deprel in relations:
                                relations.append(deprel)

        return relations

