def _validate_pianoroll(pianoroll):
    """Raise an error if the input array is not a standard pianoroll."""
    if not isinstance(pianoroll, np.ndarray):
        raise TypeError("`pianoroll` must be of np.ndarray type.")
    if not (np.issubdtype(pianoroll.dtype, np.bool_)
            or np.issubdtype(pianoroll.dtype, np.number)):
        raise TypeError("The data type of `pianoroll` must be np.bool_ or a "
                        "subdtype of  np.number.")
    if pianoroll.ndim != 2:
        raise ValueError("`pianoroll` must have exactly two dimensions.")
    if pianoroll.shape[1] != 128:
        raise ValueError("The length of the second axis of `pianoroll` must be "
                         "128.")

def prepare_check(data):
    """Prepare check for catalog endpoint

    Parameters:
        data (Object or ObjectID): Check ID or check definition
    Returns:
        Tuple[str, dict]: where first is ID and second is check definition
    """
    if not data:
        return None, {}

    if isinstance(data, str):
        return data, {}

    result = {}
    if "ID" in data:
        result["CheckID"] = data["ID"]
    for k in ("Node", "CheckID", "Name", "Notes", "Status", "ServiceID"):
        if k in data:
            result[k] = data[k]
    if list(result) == ["CheckID"]:
        return result["CheckID"], {}
    return result.get("CheckID"), result

def get_encoder(encoding):
    """Creates encoder object for the given encoding.

    :param encoding: desired output encoding protocol.
    :type encoding: Encoding
    :return: corresponding IEncoder object
    :rtype: IEncoder
    """
    if encoding == Encoding.V1_THRIFT:
        return _V1ThriftEncoder()
    if encoding == Encoding.V1_JSON:
        return _V1JSONEncoder()
    if encoding == Encoding.V2_JSON:
        return _V2JSONEncoder()
    if encoding == Encoding.V2_PROTO3:
        return _V2ProtobufEncoder()
    raise ZipkinError('Unknown encoding: {}'.format(encoding))

