def data_dtype(self):
        """Data type of the data block as determined from `header`.

        If no header is available (i.e., before it has been initialized),
        or the header entry ``'mode'`` is missing, the data type gained
        from the ``dtype`` argument in the initializer is returned.
        Otherwise, it is determined from ``mode``.
        """
        if not self.header:
            return self._init_data_dtype
        try:
            mode = int(self.header['mode']['value'])
        except KeyError:
            return self._init_data_dtype
        else:
            try:
                return MRC_MODE_TO_NPY_DTYPE[mode]
            except KeyError:
                raise ValueError('data mode {} not supported'.format(mode))

def is_installed(prog):
    """Return whether or not a given executable is installed on the machine."""
    with open(os.devnull, 'w') as devnull:
        try:
            if os.name == 'nt':
                retcode = subprocess.call(['where', prog], stdout=devnull)
            else:
                retcode = subprocess.call(['which', prog], stdout=devnull)
        except OSError as e:
            # If where or which doesn't exist, a "ENOENT" error will occur (The
            # FileNotFoundError subclass on Python 3).
            if e.errno != errno.ENOENT:
                raise
            retcode = 1

    return retcode == 0

def ignore_broken_pipe():
    """ If a shellish program has redirected stdio it is subject to erroneous
    "ignored" exceptions during the interpretor shutdown. This essentially
    beats the interpretor to the punch by closing them early and ignoring any
    broken pipe exceptions. """
    for f in sys.stdin, sys.stdout, sys.stderr:
        try:
            f.close()
        except BrokenPipeError:
            pass

