def _apply_st(self, doc_loader, **kwargs):
        """Run the UDF single-threaded, optionally with progress bar"""
        udf = self.udf_class(**self.udf_init_kwargs)

        # Run single-thread
        for doc in doc_loader:
            if self.pb is not None:
                self.pb.update(1)

            udf.session.add_all(y for y in udf.apply(doc, **kwargs))

        # Commit session and close progress bar if applicable
        udf.session.commit()

def lnlike(self, p):
        """Log-likelihood of model at given parameters


        :param p: 
            mass, log10(age), feh, [distance, A_V (extinction)].
            Final two should only be provided if ``self.fit_for_distance``
            is ``True``; that is, apparent magnitudes are provided.

        :return:
           log-likelihood.  Will be -np.inf if values out of range.

        """

        if not self._props_cleaned:
            self._clean_props()

        if not self.use_emcee:
            fit_for_distance = True
            mass, age, feh, dist, AV = (p[0], p[1], p[2], p[3], p[4])
        else:
            if len(p)==5:
                fit_for_distance = True
                mass,age,feh,dist,AV = p
            elif len(p)==3:
                fit_for_distance = False
                mass,age,feh = p

        if mass < self.ic.minmass or mass > self.ic.maxmass \
           or age < self.ic.minage or age > self.ic.maxage \
           or feh < self.ic.minfeh or feh > self.ic.maxfeh:
            return -np.inf
        if fit_for_distance:
            if dist < 0 or AV < 0 or dist > self.max_distance:
                return -np.inf
            if AV > self.maxAV:
                return -np.inf

        if self.min_logg is not None:
            logg = self.ic.logg(mass,age,feh)
            if logg < self.min_logg:
                return -np.inf

        logl = 0
        for prop in self.properties.keys():
            try:
                val,err = self.properties[prop]
            except TypeError:
                #property not appropriate for fitting (e.g. no error provided)
                continue

            if prop in self.ic.bands:
                if not fit_for_distance:
                    raise ValueError('must fit for mass, age, feh, dist, A_V if apparent magnitudes provided.')
                mod = self.ic.mag[prop](mass,age,feh) + 5*np.log10(dist) - 5
                A = AV*EXTINCTION[prop]
                mod += A
            elif re.search('delta_',prop):
                continue
            elif prop=='feh':
                mod = feh
            elif prop=='parallax':
                mod = 1./dist * 1000
            else:
                mod = getattr(self.ic,prop)(mass,age,feh)

            logl += -(val-mod)**2/(2*err**2) + np.log(1/(err*np.sqrt(2*np.pi)))

        if np.isnan(logl):
            logl = -np.inf

        return logl

def xpoll(self, channel_id=None, json=None, ack=False,
              follow=False, pause=None, **kwargs):
        """Retrieve logType, event entries iteratively in a non-greedy manner.

        Generator function to return logType, event entries from poll
        API request.

        Args:
            channel_id (str): The channel ID.
            json (dict): Payload/request body.
            ack (bool): True to acknowledge read.
            follow (bool): True to continue polling after channelId empty.
            pause (float): Seconds to sleep between poll when follow and channelId empty.
            **kwargs: Supported :meth:`~pancloud.httpclient.HTTPClient.request` parameters.

        Yields:
            dictionary with single logType and event entries.

        """
        def _ack(channel_id, **kwargs):
            r = self.ack(channel_id, **kwargs)

            if not (200 <= r.status_code < 300):
                try:
                    r_json = r.json()
                except ValueError as e:
                    raise PanCloudError('Invalid JSON: %s' % e)
                if 'errorCode' in r_json and 'errorMessage' in r_json:
                    raise PanCloudError('%s: %s' %
                                        (r_json['errorCode'],
                                         r_json['errorMessage']))
                else:
                    raise PanCloudError('%s %s' % (r.status_code,
                                                   r.reason))

            if r.status_code == 200:
                return
            else:
                raise PanCloudError('ack: status_code: %d' %
                                    r.status_code)

        while True:
            r = self.poll(channel_id, json, **kwargs)
            try:
                r_json = r.json()
            except ValueError as e:
                raise PanCloudError('Invalid JSON: %s' % e)

            if not (200 <= r.status_code < 300):
                if 'errorCode' in r_json and 'errorMessage' in r_json:
                    raise PanCloudError('%s: %s' %
                                        (r_json['errorCode'],
                                         r_json['errorMessage']))
                else:
                    raise PanCloudError('%s %s' % (r.status_code,
                                                   r.reason))

            if not r_json and not follow:
                return

            for x in r_json:
                yield x

            # XXX don't ack if empty response?
            if ack:
                _ack(channel_id, **kwargs)

            if not r_json and pause is not None:
                self._debug('sleep %.2fs', pause)
                time.sleep(pause)

def pairwise(X):
    M = X.shape[0]
    N = X.shape[1]
    D = numpy.zeros((M,N))
    "omp parallel for private(i,j,d,k,tmp)"
    for i in xrange(M):
        for j in xrange(M):
            d = 0.0
            for k in xrange(N):
                tmp = X[i,k] - X[j,k]
                d += tmp * tmp
            D[i,j] = math.sqrt(d)
    return D

def generators():
    """
    List all the available generators.
    """
    from populous import generators

    base = generators.Generator

    for name in dir(generators):
        generator = getattr(generators, name)

        if isinstance(generator, type) and issubclass(generator, base):
            name = generator.__name__
            doc = (generator.__doc__ or '').strip()

            if doc:
                click.echo("{} - {}".format(name, doc))
            else:
                click.echo(name)

def generate_add_user_command(proposed_user=None, manage_home=None):
    """Generate command to add a user.

    args:
        proposed_user (User): User
        manage_home: bool

    returns:
        list: The command string split into shell-like syntax
    """
    command = None
    if get_platform() in ('Linux', 'OpenBSD'):
        command = '{0} {1}'.format(sudo_check(), LINUX_CMD_USERADD)
        if proposed_user.uid:
            command = '{0} -u {1}'.format(command, proposed_user.uid)
        if proposed_user.gid:
            command = '{0} -g {1}'.format(command, proposed_user.gid)
        if proposed_user.gecos:
            command = '{0} -c \'{1}\''.format(command, proposed_user.gecos)
        if manage_home:
            if proposed_user.home_dir:
                if os.path.exists(proposed_user.home_dir):
                    command = '{0} -d {1}'.format(command, proposed_user.home_dir)
            elif not os.path.exists('/home/{0}'.format(proposed_user.name)):
                command = '{0} -m'.format(command)
        if proposed_user.shell:
            command = '{0} -s {1}'.format(command, proposed_user.shell)
        command = '{0} {1}'.format(command, proposed_user.name)
    elif get_platform() == 'FreeBSD':  # pragma: FreeBSD
        command = '{0} {1} useradd'.format(sudo_check(), FREEBSD_CMD_PW)
        if proposed_user.uid:
            command = '{0} -u {1}'.format(command, proposed_user.uid)
        if proposed_user.gid:
            command = '{0} -g {1}'.format(command, proposed_user.gid)
        if proposed_user.gecos:
            command = '{0} -c \'{1}\''.format(command, proposed_user.gecos)
        if manage_home:
            if proposed_user.home_dir:
                command = '{0} -d {1}'.format(command, proposed_user.home_dir)
            else:
                command = '{0} -m'.format(command)
        if proposed_user.shell:
            command = '{0} -s {1}'.format(command, proposed_user.shell)
        command = '{0} -n {1}'.format(command, proposed_user.name)

    if command:
        return shlex.split(str(command))

